$modulePath = Join-Path $PSScriptRoot '..\modules\SourceInventory.psm1'
if (Test-Path -LiteralPath $modulePath) { Import-Module $modulePath -Force } else { function Get-ArchitectureSourceInventory { throw 'SourceInventory.psm1 does not exist.' } }
Describe 'Get-ArchitectureSourceInventory' {
 BeforeEach { $source=Join-Path $TestDrive 'source'; New-Item -ItemType Directory -Path (Join-Path $source 'nested') -Force|Out-Null; [IO.File]::WriteAllText((Join-Path $source 'b.txt'),'beta',[Text.UTF8Encoding]::new($false)); [IO.File]::WriteAllText((Join-Path $source 'nested\a.txt'),'alpha',[Text.UTF8Encoding]::new($false)) }
 It 'returns ordinally sorted relative paths, byte counts, and lowercase SHA-256 values' { $result=Get-ArchitectureSourceInventory -SourceRoot $source -GeneratedUtc '2026-09-17T12:00:00Z'; $result.schemaVersion|Should -Be '1.0'; $result.generatedUtc|Should -Be '2026-09-17T12:00:00Z'; $result.files.relativePath|Should -Be @('b.txt','nested/a.txt'); $result.files[0].bytes|Should -Be 4; $result.files[1].bytes|Should -Be 5; $result.files[0].sha256|Should -Match '^[0-9a-f]{64}$'; $result.totalCount|Should -Be 2; $result.totalBytes|Should -Be 9 }
 It 'rejects nested Git metadata' { $rootGit=Join-Path $source '.git'; New-Item -ItemType Directory -Path $rootGit|Out-Null; { Get-ArchitectureSourceInventory -SourceRoot $source -GeneratedUtc '2026-09-17T12:00:00Z' }|Should -Throw '*Nested Git metadata*'; Remove-Item -LiteralPath $rootGit -Recurse -Force; $nestedGit=Join-Path $source 'nested\.git'; New-Item -ItemType Directory -Path $nestedGit|Out-Null; { Get-ArchitectureSourceInventory -SourceRoot $source -GeneratedUtc '2026-09-17T12:00:00Z' }|Should -Throw '*Nested Git metadata*' }
}
